describe('retries', () => {
  it('retries retryable statuses up to maxRetries with the same idempotency key', async () => {
    await withServer(
      (request, response) => {
        if (request.n < 3) sendJSON(response, request.n === 1 ? 503 : 429, errorBody('unavailable_error', 'busy'), { 'retry-after-ms': '5' });
        else sendJSON(response, 200, { id: 'ep_1' });
      },
      async (server) => {
        const events: LogEvent[] = [];
        const client = server.client({ logger: (event) => events.push(event) });
        const { data, response } = await client.webhooks.createEndpoint('ws', { url: 'https://example.com/hook', event_types: [] }).withResponse();
        assert.equal((data as { id: string }).id, 'ep_1');
        assert.equal(response.attempts, 3);
        assert.equal(server.requests.length, 3);
        const keys = server.requests.map((r) => r.headers['idempotency-key']);
        assert.equal(typeof keys[0], 'string');
        assert.deepEqual(keys, [keys[0], keys[0], keys[0]]);
        assert.deepEqual(
          events.map((e) => e.kind),
          ['request', 'response', 'retry', 'request', 'response', 'retry', 'request', 'response'],
        );
        assert.equal(events[2]?.delayMs, 5);
      },
    );
  });

  it('gives up after maxRetries and raises the last error', async () => {
    await withServer(
      (_request, response) => {
        sendJSON(response, 503, errorBody('unavailable_error', 'busy'), { 'retry-after-ms': '1' });
      },
      async (server) => {
        const err = await rejection(server.client().companies.list());
        assert.ok(err instanceof UnavailableError);
        assert.equal(server.requests.length, 3);
        const once = await rejection(server.client().companies.list({ maxRetries: 0 }));
        assert.ok(once instanceof UnavailableError);
        assert.equal(server.requests.length, 4);
      },
    );
  });

  it('uses exponential backoff with jitter when the server names no delay', async () => {
    await withServer(
      (request, response) => {
        if (request.n === 1) sendJSON(response, 500, errorBody('api_error', 'boom'));
        else sendJSON(response, 200, { data: [] });
      },
      async (server) => {
        const events: LogEvent[] = [];
        const started = Date.now();
        await server.client({ logger: (event) => events.push(event) }).companies.list();
        const waited = Date.now() - started;
        const retry = events.find((e) => e.kind === 'retry');
        assert.ok(retry?.delayMs !== undefined && retry.delayMs >= 375 && retry.delayMs <= 500, String(retry?.delayMs));
        assert.ok(waited >= 370, String(waited));
      },
    );
  });

  it('uses the computed backoff, not an immediate retry, for a Retry-After of zero or in the past', async () => {
    const headersList: Array<Record<string, string>> = [
      { 'retry-after': '0' },
      { 'retry-after-ms': '0' },
      { 'retry-after': 'Wed, 21 Oct 2015 07:28:00 GMT' },
      { 'retry-after': '-5' },
    ];
    for (const headers of headersList) {
      const at: number[] = [];
      await withServer(
        (request, response) => {
          at.push(Date.now());
          if (request.n === 1) sendJSON(response, 503, errorBody('unavailable_error', 'busy'), headers);
          else sendJSON(response, 200, { data: [] });
        },
        async (server) => {
          const events: LogEvent[] = [];
          await server.client({ logger: (event) => events.push(event) }).companies.list();
          const retry = events.find((e) => e.kind === 'retry');
          assert.ok(retry?.delayMs !== undefined && retry.delayMs >= 375 && retry.delayMs <= 500, JSON.stringify(headers) + ': ' + String(retry?.delayMs));
          assert.ok((at[1] ?? 0) - (at[0] ?? 0) >= 350, JSON.stringify(headers) + ': the second attempt came after ' + String((at[1] ?? 0) - (at[0] ?? 0)) + ' ms');
        },
      );
    }
  });

  it('does not repeat a write that has no idempotency key, and does not retry client errors', async () => {
    await withServer(
      (_request, response) => {
        sendJSON(response, 503, errorBody('unavailable_error', 'busy'), { 'retry-after-ms': '1' });
      },
      async (server) => {
        const client = server.client();
        // PATCH declares no Idempotency-Key header in the contract.
        assert.ok((await rejection(client.webhooks.updateEndpoint('ws', 'ep', {}))) instanceof UnavailableError);
        assert.equal(server.requests.length, 1);
        assert.equal(server.requests[0]?.headers['idempotency-key'], undefined);
        // The caller's own key makes the same call repeatable.
        assert.ok((await rejection(client.webhooks.updateEndpoint('ws', 'ep', {}, { idempotencyKey: 'my-key-1' }))) instanceof UnavailableError);
        assert.equal(server.requests.length, 4);
        assert.deepEqual(
          server.requests.slice(1).map((r) => r.headers['idempotency-key']),
          ['my-key-1', 'my-key-1', 'my-key-1'],
        );
      },
    );
    await withServer(
      (_request, response) => {
        sendJSON(response, 409, errorBody('conflict_error', 'conflict'));
      },
      async (server) => {
        await rejection(server.client().companies.list());
        assert.equal(server.requests.length, 1);
      },
    );
  });

  it('retries a connection failure of a repeatable request', async () => {
    let n = 0;
    const { fetch, calls } = fakeFetch(() => {
      n++;
      if (n === 1) throw new TypeError('fetch failed', { cause: new Error('ECONNRESET') });
      return json({ data: [] });
    });
    const client = new Tungo({ apiKey: 'k', baseUrl: 'https://x.example', fetch });
    const { response } = await client.companies.list().withResponse();
    assert.equal(response.attempts, 2);
    assert.equal(calls.length, 2);
  });
});

describe('timeouts and cancellation', () => {
  it('times out when the server does not answer, and retries a repeatable request', async () => {
    await withServer(
      async (request, response) => {
        if (request.n === 1) await delay(1000);
        sendJSON(response, 200, { data: [] });
      },
      async (server) => {
        const client = server.client();
        const err = await rejection(client.companies.list({ timeout: 100, maxRetries: 0 }));
        assert.ok(err instanceof TimeoutError);
        assert.ok(!(err instanceof APIError));
        assert.equal(err.timeout, 100);
        assert.match(err.message, /GET \/v1\/companies timed out after 100 ms/);
      },
    );
  });

  it('treats Infinity and delays beyond the timer limit as "no time limit" instead of failing at once', async () => {
    await withServer(
      async (request, response) => {
        await delay(60);
        if (request.path.endsWith('/events')) {
          response.writeHead(200, { 'content-type': 'text/event-stream' });
          response.write('event: done\ndata: {"type":"done","stop_reason":"end_turn"}\n\n');
          await delay(60);
          response.end();
        } else {
          sendJSON(response, 200, { data: [], dialog_id: 'd', errors: [] });
        }
      },
      async (server) => {
        for (const unlimited of [Number.POSITIVE_INFINITY, 2 ** 31, 2 ** 31 - 1, 1e15]) {
          const client = server.client({ timeout: unlimited, longRunningTimeout: unlimited, streamIdleTimeout: unlimited, maxRetries: 0 });
          assert.deepEqual((await client.companies.list()).data, [], String(unlimited));
          await client.ask('co', 'q');
          assert.equal(await drain(client.chat.listEvents('co', 'dlg')), 1, String(unlimited));
          const perRequest = server.client({ maxRetries: 0 });
          assert.deepEqual((await perRequest.companies.list({ timeout: unlimited })).data, [], String(unlimited));
          assert.equal(await drain(perRequest.chat.listEvents('co', 'dlg', undefined, { streamIdleTimeout: unlimited })), 1, String(unlimited));
        }
        // Zero is not "no timeout": it is rejected.
        assert.ok((await rejection(server.client().companies.list({ timeout: 0 }))) instanceof ConfigError);
      },
    );
  });

  it('applies the timeout to the body, not only to the headers', async () => {
    await withServer(
      (_request, response) => {
        response.writeHead(200, { 'content-type': 'application/json' });
        response.write('{"data":[');
        // The body never completes.
      },
      async (server) => {
        const started = Date.now();
        const err = await rejection(server.client({ maxRetries: 0 }).companies.list({ timeout: 200 }));
        assert.ok(err instanceof TimeoutError, String(err));
        assert.ok(Date.now() - started < 3000);
      },
    );
  });

  it('gives non-streaming chat turns the long-running timeout', async () => {
    await withServer(
      async (request, response) => {
        await delay(300);
        sendJSON(response, 200, request.path.endsWith('/chat') ? { text: 'ok', dialog_id: 'd', turn_no: 1 } : { data: [] });
      },
      async (server) => {
        const client = server.client({ timeout: 100, longRunningTimeout: 5000, maxRetries: 0 });
        assert.ok((await rejection(client.companies.list())) instanceof TimeoutError);
        const turn = await client.chat.create('co', { message: 'q' });
        assert.equal((turn as { text?: string }).text, 'ok');
        // An explicit per-request timeout still wins.
        assert.ok((await rejection(client.chat.create('co', { message: 'q' }, { timeout: 50 }))) instanceof TimeoutError);
      },
    );
  });

  it('cancels with the caller signal, keeping the timeout in force', async () => {
    await withServer(
      async (_request, response) => {
        await delay(2000);
        sendJSON(response, 200, { data: [] });
      },
      async (server) => {
        const client = server.client({ maxRetries: 0 });
        const controller = new AbortController();
        setTimeout(() => {
          controller.abort();
        }, 50);
        const started = Date.now();
        const aborted = await rejection(client.companies.list({ signal: controller.signal }));
        assert.ok(aborted instanceof AbortError, String(aborted));
        assert.ok(!(aborted instanceof TimeoutError));
        assert.ok(Date.now() - started < 1500);

        // A signal that never fires must not disable the timeout.
        const idle = new AbortController();
        assert.ok((await rejection(client.companies.list({ signal: idle.signal, timeout: 100 }))) instanceof TimeoutError);

        // An already aborted signal fails before any request is sent.
        const before = server.requests.length;
        const dead = new AbortController();
        dead.abort();
        assert.ok((await rejection(client.companies.list({ signal: dead.signal }))) instanceof AbortError);
        assert.equal(server.requests.length, before);
      },
    );
  });

  it('cancels the wait between retries', async () => {
    await withServer(
      (_request, response) => {
        sendJSON(response, 503, errorBody('unavailable_error', 'busy'), { 'retry-after': '30' });
      },
      async (server) => {
        const controller = new AbortController();
        setTimeout(() => {
          controller.abort();
        }, 100);
        const started = Date.now();
        const err = await rejection(server.client().companies.list({ signal: controller.signal }));
        assert.ok(err instanceof AbortError);
        assert.ok(Date.now() - started < 2000);
        assert.equal(server.requests.length, 1);
      },
    );
  });
});

describe('logger', () => {
  it('receives route templates and no secrets', async () => {
    await withServer(
      (_request, response) => {
        sendJSON(response, 200, { accepted: true }, { 'x-request-id': 'req_log' });
      },
      async (server) => {
        const events: LogEvent[] = [];
        const client = server.client({
          logger: (event) => {
            events.push(event);
            throw new Error('a failing logger must not break the call');
          },
        });
        await client.companies.get('co_secret_id');
        await client.sendHook('hook_token_SECRET', { a: 1 }, { secret: 'hook_signing_SECRET' });
        const text = JSON.stringify(events);
        assert.ok(!text.includes(API_KEY) && !text.includes('hook_token_SECRET') && !text.includes('hook_signing_SECRET') && !text.includes('co_secret_id'), text);
        assert.deepEqual(events[0], { kind: 'request', method: 'GET', route: '/v1/companies/{co}', attempt: 1 });
        assert.equal(events[1]?.kind, 'response');
        assert.equal(events[1]?.status, 200);
        assert.equal(events[1]?.requestId, 'req_log');
        assert.equal(typeof events[1]?.durationMs, 'number');
        assert.equal(events[2]?.route, '/hooks/{token}');
      },
    );
  });
});
